"""Immersive welcome visuals, lifecycle, accessibility and essential controls."""
import argparse,json
from pathlib import Path
from playwright.sync_api import sync_playwright
parser=argparse.ArgumentParser();parser.add_argument('--url',default='http://127.0.0.1:8093');parser.add_argument('--cdp');parser.add_argument('--output',default='validation/immersive-welcome');args=parser.parse_args();out=Path(args.output);out.mkdir(parents=True,exist_ok=True)
with sync_playwright() as p:
 b=p.chromium.connect_over_cdp(args.cdp) if args.cdp else p.chromium.launch();ctx=b.new_context(viewport={'width':800,'height':480});pg=ctx.new_page();errors=[];pg.on('pageerror',lambda e:errors.append(str(e)));pg.add_init_script('''window.welcomeDraws=0;const clear=CanvasRenderingContext2D.prototype.clearRect;CanvasRenderingContext2D.prototype.clearRect=function(...args){if(this.canvas.id==='welcome-atmosphere')window.welcomeDraws++;return clear.apply(this,args)};''');pg.goto(args.url);pg.wait_for_function('()=>document.querySelector("#connection").textContent.includes("Connected")');reports=[]
 for w,h in [(800,480),(1280,720),(1920,1080)]:
  pg.set_viewport_size({'width':w,'height':h});pg.wait_for_timeout(1100);assert pg.locator('#dashboard .tile,#candy-value,#add-candy,#remove-candy').count()==0
  assert pg.locator('#dashboard [data-countdown] .digit').count()==3
  assert pg.locator('.welcome-countdown').evaluate('(e)=>getComputedStyle(e).animationName')=='welcome-emerge'
  bounds=pg.locator('#pumpkin,#weather-location,#ambience-toggle').evaluate_all('els=>els.map(e=>{const r=e.getBoundingClientRect(),m=document.querySelector("main").getBoundingClientRect();return {id:e.id,width:r.width,height:r.height,visible:r.top>=m.top&&r.bottom<=m.bottom+1&&r.left>=0&&r.right<=innerWidth}})')
  assert all(r['width']>=48 and r['height']>=48 and r['visible'] for r in bounds),bounds
  assert pg.locator('#dashboard').evaluate('(e)=>e.scrollHeight<=e.clientHeight+1')
  before=pg.evaluate('welcomeDraws');pg.wait_for_timeout(2100);fps=(pg.evaluate('welcomeDraws')-before)/2.1;assert fps>0
  pg.screenshot(path=str(out/f'welcome-{w}.png'));reports.append({'width':w,'height':h,'controls':bounds,'canvas_draw_fps':round(fps,1)})
 pg.set_viewport_size({'width':800,'height':480});pg.click('[data-screen="haunt"]');pg.wait_for_timeout(100);before=pg.evaluate('welcomeDraws');pg.wait_for_timeout(1200);assert pg.evaluate('welcomeDraws')==before,'Hidden-screen canvas still drawing';pg.click('[data-screen="dashboard"]');pg.click('#weather-location');pg.wait_for_timeout(100);before=pg.evaluate('welcomeDraws');pg.wait_for_timeout(1200);assert pg.evaluate('welcomeDraws')==before,'Canvas still drawing behind modal';pg.locator('#settings-dialog [data-close]').click()
 pg.click('#ambience-toggle');pg.wait_for_function('()=>document.querySelector("#ambience-toggle").getAttribute("aria-pressed")==="true"');pg.wait_for_function('()=>document.querySelector("#ambience-player").currentTime>.05');pg.click('#ambience-toggle');assert pg.locator('#ambience-player').evaluate('(e)=>e.paused');pg.focus('#pumpkin');pg.keyboard.press('Enter');pg.wait_for_selector('[data-choice="play"]');pg.click('#visitor-back');pg.wait_for_function('()=>!document.querySelector("#pumpkin").disabled')
 pg.evaluate("()=>fetch('/api/settings',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({reduced_motion:true})})");pg.wait_for_timeout(1300);before=pg.evaluate('welcomeDraws');pg.wait_for_timeout(1200);assert pg.evaluate('welcomeDraws')-before<=2;assert pg.locator('.welcome-countdown').evaluate('(e)=>getComputedStyle(e).animationName')=='none';pg.evaluate("()=>fetch('/api/settings',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({reduced_motion:false})})");assert not errors,errors
 (out/'report.json').write_text(json.dumps({'layouts':reports,'no_cards_or_candy':True,'hidden_animation_paused':True,'modal_animation_paused':True,'ambient_toggle':True,'keyboard_adventure':True,'reduced_motion':True,'errors':errors},indent=2));print(json.dumps({'layouts':[{'size':[r['width'],r['height']],'fps':r['canvas_draw_fps']} for r in reports],'errors':errors}));ctx.close()
 if not args.cdp:b.close()
